import json, random, sys, time
sys.path.insert(0,'/workspace/tmp')
from harness import run

def build(style, seed=1):
    rng = random.Random(seed)
    nodes = ['node-%02d' % i for i in range(64)]
    flows = []
    for i in range(22):
        if style == 'shared':
            path = rng.sample(nodes[:12], 9)
        elif style == 'wide':
            path = rng.sample(nodes, 9)
        elif style == 'clique':
            path = rng.sample(nodes[:6], min(6, 9))
        else:
            path = rng.sample(nodes, rng.randint(2, 9))
        H = 256
        kinds = ['K']*200 + ['D']*50 + ['Z']*4 + ['Q','T']
        rng.shuffle(kinds)
        flows.append({'id':'flow-%02d'%i,'path':path,'template':bytes(rng.randrange(256) for _ in range(H)).hex(),'kinds':''.join(kinds)})
    caps = {}
    for n in nodes:
        caps[n] = rng.choice([0,1,2,3,512,512])
    offers = {}
    for f in flows:
        H = 256
        hb = bytearray(rng.randrange(256) for _ in range(H))
        for pos,c in enumerate(f['kinds']):
            if c=='K': hb[pos]=int(f['template'][2*pos:2*pos+2],16)
            elif c=='Q': hb[pos]=3
            elif c=='T': hb[pos]=250
        offers[f['id']] = [{'header':bytes(hb).hex(),'count':rng.randint(1,10**9)}]
    return {'mode':'plan','capacities':caps,'flows':flows,'warmup':0,'pinned':[],'offers':offers}

for style in ['shared','wide','clique','mixed']:
    req = build(style)
    t=time.time()
    out = run([req])
    print(style, '%.2fs' % (time.time()-t), json.dumps(out[0])[:200])
EOF
